package com.bank.symmetry;

import java.util.logging.Logger;

public class SymmetryAnalyzer {

    private static final Logger log = Logger.getLogger(SymmetryAnalyzer.class.getName());

    public int longestPalindromeSubseq(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;                              // single char is a palindrome
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(i) == s.charAt(j)) {
                    dp[i][j] = dp[i + 1][j - 1] + 2;    // matching ends wrap inner + 2
                } else {
                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]); // drop one end
                }
            }
        }
        int result = dp[0][n - 1];
        log.info(() -> "Longest palindromic subsequence = " + result);
        return result;
    }
}
