package com.bank.symmetry;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PalindromeSubseqDemo {

    private static final Logger log = Logger.getLogger(PalindromeSubseqDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Symmetry Analyzer (Palindromic Subsequence)");
        SymmetryAnalyzer analyzer = new SymmetryAnalyzer();
        log.info("bbbab → " + analyzer.longestPalindromeSubseq("bbbab")); // 4 (bbbb)
        log.info("cbbd → " + analyzer.longestPalindromeSubseq("cbbd"));    // 2 (bb)
    }
}
